-- HALO: check that migration 0029 is applied correctly. Read only.
-- Generated by scripts/build-apply-bundle.mjs from each migration's own verification query.
-- Expect one row: all_migrations_ok = true and failing = none.

with checks as (
  select '0029' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        (select relrowsecurity from pg_class where oid = 'public.household_summaries'::regclass) as rls_on,
        (select count(*) from pg_policies
          where schemaname = 'public' and tablename = 'household_summaries') = 0
          as no_policies,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           where has_any_column_privilege(r, 'public.household_summaries', 'SELECT')
              or has_any_column_privilege(r, 'public.household_summaries', 'INSERT')
              or has_any_column_privilege(r, 'public.household_summaries', 'UPDATE')
              or has_table_privilege(r, 'public.household_summaries', 'DELETE'))
          as no_client_access,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           cross join unnest(array['public.household_summary_json(public.household_summaries)',
                                   'public.read_household_summaries(uuid, integer)',
                                   'public.read_household_summary(uuid, uuid)',
                                   'public.household_summary_usage(uuid)',
                                   'public.commit_household_summary(uuid, uuid, jsonb)',
                                   'public.summary_privacy_counts(uuid)',
                                   'public.guard_household_summary_update()',
                                   'public.guard_settled_summary_operation()',
                                   'public.clear_summaries_with_privacy_clear()']) as f
           where has_function_privilege(r, f, 'EXECUTE'))
          and (select bool_and(has_function_privilege('service_role', f, 'EXECUTE'))
                 from unnest(array['public.household_summary_json(public.household_summaries)',
                                   'public.read_household_summaries(uuid, integer)',
                                   'public.read_household_summary(uuid, uuid)',
                                   'public.household_summary_usage(uuid)',
                                   'public.commit_household_summary(uuid, uuid, jsonb)',
                                   'public.summary_privacy_counts(uuid)']) as f)
          as functions_service_role_only,
        (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
          where n.nspname = 'public' and not p.prosecdef and 'search_path=public' = any (p.proconfig)
            and p.proname in ('household_summary_json', 'read_household_summaries', 'read_household_summary',
                              'household_summary_usage', 'commit_household_summary', 'summary_privacy_counts',
                              'guard_household_summary_update', 'guard_settled_summary_operation',
                              'clear_summaries_with_privacy_clear')) = 9
          as functions_invoker_pinned,
        (select count(*) from pg_trigger
          where (tgrelid = 'public.operations'::regclass
                 and tgname in ('operations_summary_settled_guard', 'operations_privacy_clear_summaries'))
             or (tgrelid = 'public.household_summaries'::regclass and tgname = 'household_summaries_immutable')) = 3
          as triggers_on,
        (select count(*) from pg_constraint
          where conrelid = 'public.household_summaries'::regclass and contype in ('c', 'u')) = 5
          as five_constraints
  ) q, jsonb_each_text(to_jsonb(q)) j
)
select bool_and(ok) as all_migrations_ok,
       count(*) as checks_run,
       coalesce(string_agg(migration || '.' || check_name, ', ') filter (where not ok), 'none') as failing
from checks;
